  const waits = [];
  const sleep = (ms) => { waits.push(ms); return Promise.resolve(); };
  sleep.waits = waits;
  return sleep;
}
// a fn that fails `failN` times, then succeeds
function flaky(failN, value = 'ok') {
  let calls = 0;
  const fn = async () => {
    calls += 1;
    if (calls <= failN) throw new Error(`fail ${calls}`);
    return value;
  };
  fn.callCount = () => calls;
  return fn;
}

