  const calls = [];
  const fetchPage = async (cursor) => {
    const start = cursor ?? 0;
    calls.push(cursor);
    const slice = items.slice(start, start + size);
    const next = start + size < items.length ? start + size : null;
    return { items: slice, nextCursor: next };
  };
  fetchPage.calls = calls;
  return fetchPage;
}

